// Package data embeds SIAPA's rotation zones, colonia list and weekly schedule, and INE's other colonias.
package data

import _ "embed"

//go:embed zonas.geojson
var Zonas []byte

//go:embed colonias.json
var Colonias []byte

//go:embed rotation.json
var Rotation []byte

// OtrasColonias are the colonias in INE's cartography that aren't on SIAPA's list,
// generated by pipelines/colonias_poligonos.py.
//
//go:embed otras_colonias.json
var OtrasColonias []byte

// ColoniasMapa lists each colonia on /reportes once as [name, municipio, postal code, zones],
// generated from web/colonias_siapa.topo.json by pipelines/mapa_colonias.py.
//
//go:embed colonias_mapa.json
var ColoniasMapa []byte
